static int r8153_phy_status(struct r8152 *tp, u16 desired)
{
	int i, ret;
	u16 data;

	for (i = 0; i < 500; i++) {
		ret = ocp_reg_read(tp, OCP_PHY_STATUS, &data);
		if (ret < 0)
			return ret;

		data &= PHY_STAT_MASK;
		if (desired) {
			if (data == desired)
				break;
		} else if (data == PHY_STAT_LAN_ON || data == PHY_STAT_PWRDN ||
			   data == PHY_STAT_EXT_INIT) {
			break;
		}

		msleep(20);
		if (test_bit(RTL8152_UNPLUG, &tp->flags))
			break;
	}

	return data;
}
